class FootballV510Tests {
 static int checks,failures;static object Get(object o,string n){return o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);}static void Set(object o,string n,object v){o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).SetValue(o,v);}static object Call(object o,string n,params object[] a){return o.GetType().GetMethod(n,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(o,a);}static void Check(string n,bool v){checks++;Console.WriteLine((v?"PASS ":"FAIL ")+n);if(!v)failures++;}
 static void Capture(Window pet,FootballWorld ball,string path){var sprite=(SpriteView)Get(pet,"sprite");double scale=(double)Get(pet,"scale"),pad=(pet.Width-192*scale)/2;var visual=new DrawingVisual();RenderOptions.SetBitmapScalingMode(visual,BitmapScalingMode.NearestNeighbor);using(var dc=visual.RenderOpen()){dc.DrawRectangle(new SolidColorBrush(Color.FromRgb(18,38,53)),null,new Rect(0,0,500,500));dc.PushTransform(new TranslateTransform(130,230));typeof(SpriteView).GetMethod("OnRender",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(sprite,new object[]{dc});dc.Pop();var window=(FootballWindow)Get(pet,"footballWindow");if(window!=null&&ball.Active)dc.DrawImage(((SpriteView)window.Content).Frame,new Rect(130+ball.X-pet.Left-pad-ball.Radius,230+ball.Y-pet.Top-90-ball.Radius,ball.Radius*2,ball.Radius*2));}var bitmap=new RenderTargetBitmap(500,500,96,96,PixelFormats.Pbgra32);bitmap.Render(visual);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var f=File.Create(path))encoder.Save(f);}
 [STAThread]static int Main(string[] args){Directory.CreateDirectory(args[0]);var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};Window pet=null;try{pet=(Window)Activator.CreateInstance(typeof(ConanPet),true);pet.Show();pet.UpdateLayout();((DispatcherTimer)Get(pet,"ticker")).Stop();((DispatcherTimer)Get(pet,"skillTicker")).Stop();var messages=(BubbleQueue)Get(pet,"messages");messages.Clear();var voice=(VoiceRuntime)Get(pet,"voices");voice.Settings.Interactions=false;var ball=(FootballWorld)Get(pet,"football");var sprites=(SpriteActions)Get(pet,"signature");Check("flick/volley 12 frames and bicycle 14 frames loaded",sprites.Count("flick-up")==12&&sprites.Count("kick-play")==12&&sprites.Count("bicycle")==14);
 foreach(string action in new[]{"flick","volley","bicycle"}){Set(pet,"direction",1);Set(pet,"footballRepeatCount",1);messages.Clear();Call(pet,"StartFootball",action);double start=(double)Get(pet,"footballKickStart");bool hit=false,recovered=false;double lastX=ball.X,lastY=ball.Y;int snapshots=0;for(int i=0;i<3600&&ball.Active&&(string)Get(pet,"footballMode")!="rest";i++){double now=start+i/120.0;Call(pet,"TickFootball",now,1.0/120);if((bool)Get(pet,"footballReleased")&&(bool)Get(pet,"footballHit")){if(!hit)Capture(pet,ball,Path.Combine(args[0],action+"-contact.png"));hit=true;}if((string)Get(pet,"footballMode")=="flight")recovered=true;if(i%6==0&&i/120.0<FootballWorld.ActionDuration(action)+1.5)Capture(pet,ball,Path.Combine(args[0],action+"-"+(snapshots++).ToString("D3")+".png"));if(i==6)Check(action+" ball is not snapped during windup",action=="flick"||Math.Abs(ball.X-lastX)+Math.Abs(ball.Y-lastY)>0);}
 Check(action+" reaches real foot contact",hit);Check(action+" completes landing and recovery",recovered);Check(action+" finite performance ends with retained prop",ball.Active&&(string)Get(pet,"footballMode")=="rest");Check(action+" consumes exactly one selected round",(int)Get(pet,"footballShotsLeft")==0);}
 foreach(int facing in new[]{1,-1})foreach(int incoming in new[]{1,-1}){messages.Clear();Set(pet,"direction",facing);Set(pet,"footballRepeatCount",1);Call(pet,"StartFootball","bicycle");double time=(double)Get(pet,"footballKickStart"),scale=(double)Get(pet,"scale");Point contact=(Point)Call(pet,"FootballContact","bicycle");double sim=FootballWorld.ContactTime("bicycle")*FootballWorld.MotionRate;ball.VX=incoming*30*scale;ball.X=contact.X-ball.VX*sim;for(int i=0;i<=144;i++)Call(pet,"TickFootball",time+i/120.0,1.0/120);Check("bicycle returns incoming "+incoming+" with facing "+facing,(bool)Get(pet,"footballHit")&&Math.Sign(ball.VX)==-incoming);Capture(pet,ball,Path.Combine(args[0],"bicycle-return-"+facing+"-"+incoming+".png"));Call(pet,"StopFootball");}
 foreach(int facing in new[]{1,-1}){messages.Clear();Set(pet,"direction",facing);Call(pet,"StartFootball","bicycle");double start=(double)Get(pet,"footballKickStart"),scale=(double)Get(pet,"scale"),center=pet.Left+(pet.Width-192*scale)/2+96*scale;Check("bicycle starts behind stance "+facing,(ball.X-center)*facing<0&&Math.Sign(ball.VX)==facing&&Math.Abs(ball.X-center)>150*scale);for(int i=0;i<210;i++){Call(pet,"TickFootball",start+i/120.0,1.0/120);if(i%6==0)Capture(pet,ball,Path.Combine(args[0],"bicycle-behind-"+(facing>0?"right":"left")+"-"+(i/6).ToString("D3")+".png"));}Check("bicycle overhead foot points back "+facing,(bool)Get(pet,"footballHit")&&FootballWorld.ContactX("bicycle")<96);Check("bicycle returns behind stance "+facing,Math.Sign(ball.VX)==-facing);Call(pet,"StopFootball");}
 Set(pet,"footballRepeatCount",2);messages.Clear();Call(pet,"StartFootball","throw");Check("toss starts with visible upward toe flick",(string)Get(pet,"footballMode")=="flick");double epoch=(double)Get(pet,"footballKickStart");bool chased=false,volley=false,bicycle=false;int hits=0,previous=2;double maxLift=0;for(int i=0;i<7200&&ball.Active&&(string)Get(pet,"footballMode")!="rest";i++){Call(pet,"TickFootball",epoch+i/120.0,1.0/120);string mode=(string)Get(pet,"footballMode");chased|=mode=="chase";volley|=mode=="volley";bicycle|=mode=="bicycle";int left=(int)Get(pet,"footballShotsLeft");if(left<previous){hits+=previous-left;previous=left;}maxLift=Math.Max(maxLift,pet.Top+90+154*(double)Get(pet,"scale")-ball.Y);}
 Check("toss ball rises visibly above original head",maxLift>160);Check("combo includes chase after toe flick",chased);Check("combo performs an airborne volley",volley);Check("second round uses bicycle",bicycle);Check("two selected rounds produce exactly two shots",hits==2);Check("complete two round combo exits with retained prop",ball.Active&&(string)Get(pet,"footballMode")=="rest");Console.WriteLine("COMBO hits="+hits+" left="+Get(pet,"footballShotsLeft")+" mode="+Get(pet,"footballMode"));
 messages.Clear();Set(pet,"footballRepeatCount",1);Call(pet,"StartFootball","volley");ball.X+=400;epoch=(double)Get(pet,"footballKickStart");for(int i=0;i<120;i++)Call(pet,"TickFootball",epoch+i/120.0,1.0/120);Check("missed ball does not create phantom shot",!(bool)Get(pet,"footballHit")&&(int)Get(pet,"footballShotsLeft")==1);Call(pet,"StopFootball");
 messages.Clear();Call(pet,"StartFootball","bicycle");epoch=(double)Get(pet,"footballKickStart");Set(pet,"menuOpen",true);double x=ball.X,y=ball.Y;Call(pet,"TickFootball",epoch+.1,.1);Check("menu pauses complete new action",ball.X==x&&ball.Y==y&&!((Window)Get(pet,"footballWindow")).IsVisible);Set(pet,"menuOpen",false);Call(pet,"NotifyWorkEnd",new SkillAlert{Count=15,Key="work-end:test",Text="距离下班还有15分钟",Row=3});Check("countdown still interrupts action and retains ball",ball.Active&&(string)Get(pet,"footballMode")=="rest");messages.Clear();Call(pet,"StartFootball","flick");pet.Hide();Check("hiding still clears new action overlay",!ball.Active&&!((Window)Get(pet,"footballWindow")).IsVisible);
 }catch(Exception e){Console.WriteLine(e);failures++;}finally{if(pet!=null)pet.Close();app.Shutdown();}Console.WriteLine("Checks: "+checks+" Failures: "+failures);return failures==0?0:1;}
}
